{
  "interpretation": {
    "name": "TightenForkliftFastenersLine2AndReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 of line 2 with the shared nutrunner NR7, then return the tool to the crib and release the reservation so other lines are not blocked.",
    "constraints": [
      "The tool must be reserved before any use and released after it is returned.",
      "The tool lease must be renewed with the reservation token before every tool-using Step.",
      "transport-tool must be executed by agvexecutor.",
      "The tool must be at the station before configure-tool and tighten-fasteners.",
      "The tightening program must come from get-program and is not written into the Recipe.",
      "The tightening must be evaluated against its program and recorded for traceability (quality policy E5).",
      "The tool must be released only after it has been transported back to the crib."
    ],
    "preference": "Release the tool as early as possible so that other lines are not blocked.",
    "priority": "normal",
    "horizon": "Immediate, single execution.",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-tighten-and-return-tool",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "Deliver",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "get-prog", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Deliver",
        "next": "Tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "Finish",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten"], "dep": ["get-prog", "reserve", "transport-to-station"], "executor": null, "params": {}},
          {"name": "tighten", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve", "transport-to-station"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Finish",
        "next": null,
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": ["release"], "dep": ["reserve", "tighten"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve", "transport-to-crib"], "executor": null, "params": {}},
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten", "get-prog"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
